import{_ as e,o as a,c as d,a2 as i}from"./chunks/framework.Dj7FWXx_.js";const u=JSON.parse('{"title":"插件文章示例：B站综合插件","description":"","frontmatter":{},"headers":[],"relativePath":"reference/plugin-article-example.md","filePath":"reference/plugin-article-example.md","lastUpdated":null}'),l={name:"reference/plugin-article-example.md"};function r(o,t,n,s,c,h){return a(),d("div",null,[...t[0]||(t[0]=[i(`<h1 id="插件文章示例-b站综合插件" tabindex="-1">插件文章示例：B站综合插件 <a class="header-anchor" href="#插件文章示例-b站综合插件" aria-label="Permalink to &quot;插件文章示例：B站综合插件&quot;">​</a></h1><p>这是发布表单自动生成的插件文章示例。真实提交时在发布页填写资料、API 和事件权限即可，不需要手写市场 JSON，也不需要再次进入投稿流程。</p><h2 id="插件发布信息" tabindex="-1">插件发布信息 <a class="header-anchor" href="#插件发布信息" aria-label="Permalink to &quot;插件发布信息&quot;">​</a></h2><table tabindex="0"><thead><tr><th>项目</th><th>填写内容</th></tr></thead><tbody><tr><td>插件 ID</td><td><code>Bilibili-Utility-Suite</code></td></tr><tr><td>版本</td><td><code>1.4.6</code></td></tr><tr><td>Windows 下载地址</td><td><code>https://github.com/Carlor-Official/Bilibili-Utility-Suite/releases/download/1.4.6/BilibiliSuite-1.4.6-windows-x86_64.zip</code></td></tr><tr><td>Linux 下载地址</td><td><code>https://github.com/Carlor-Official/Bilibili-Utility-Suite/releases/download/1.4.6/BilibiliSuite-1.4.6-linux-x86_64.tar.gz</code></td></tr><tr><td>接入模式</td><td>正向 WebSocket + 反向 WebSocket</td></tr><tr><td>监听端口</td><td><code>3050</code></td></tr><tr><td>网页后台</td><td>是</td></tr><tr><td>调用 API</td><td><code>get_group_list，upload_friend_image，send_group_msg，upload_group_image</code></td></tr><tr><td>订阅事件</td><td><code>group_message，friend_message，bot_offline</code></td></tr></tbody></table><h2 id="插件简介" tabindex="-1">插件简介 <a class="header-anchor" href="#插件简介" aria-label="Permalink to &quot;插件简介&quot;">​</a></h2><p>B站综合插件通过萌卡 NT 的 WebSocket 接收机器人事件，为群聊和私聊提供 Bilibili 查询、订阅、链接解析与通知能力。Windows 与 Linux 共用同一套 Web 管理界面。</p><blockquote><p>在真实文章中，这里应放插件界面或实际消息效果截图，而不是重复放置 Logo。</p></blockquote><h2 id="主要功能" tabindex="-1">主要功能 <a class="header-anchor" href="#主要功能" aria-label="Permalink to &quot;主要功能&quot;">​</a></h2><table tabindex="0"><thead><tr><th>功能</th><th>说明</th></tr></thead><tbody><tr><td>订阅与通知</td><td>动态、直播、番剧更新等内容提醒</td></tr><tr><td>信息查询</td><td>用户、直播间、动态和视频查询</td></tr><tr><td>链接解析</td><td>识别常见 B站分享链接</td></tr><tr><td>可视化管理</td><td>账号、订阅、群配置与运行日志</td></tr><tr><td>多账号隔离</td><td>每个机器人 QQ 独立保存授权与配置</td></tr></tbody></table><h2 id="安装和对接" tabindex="-1">安装和对接 <a class="header-anchor" href="#安装和对接" aria-label="Permalink to &quot;安装和对接&quot;">​</a></h2><ol><li>在萌卡 NT 的“插件市场”找到本插件并点击“安装”。</li><li>安装完成后点击“添加服务”，确认监听端口和接入模式。</li><li>如插件提供 Web 后台，可直接从插件市场卡片打开。</li><li>在插件后台完成账号授权与功能配置。</li></ol><p>上表中的 API 与事件来自官网审核快照，是框架安装和运行时授权的唯一来源。安装包无需包含 <code>mengka-plugin.json</code>，包内字段也不会改变权限范围。</p><h2 id="使用示例" tabindex="-1">使用示例 <a class="header-anchor" href="#使用示例" aria-label="Permalink to &quot;使用示例&quot;">​</a></h2><div class="language-text vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">text</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>哔哩菜单</span></span>
<span class="line"><span>用户信息 123456</span></span>
<span class="line"><span>订阅动态 123456</span></span></code></pre></div><h2 id="当前版本" tabindex="-1">当前版本 <a class="header-anchor" href="#当前版本" aria-label="Permalink to &quot;当前版本&quot;">​</a></h2><ul><li>支持 Windows 与 Linux；</li><li>支持框架快捷安装与添加服务；</li><li>支持从插件市场打开 Web 管理后台。</li></ul><h2 id="反馈" tabindex="-1">反馈 <a class="header-anchor" href="#反馈" aria-label="Permalink to &quot;反馈&quot;">​</a></h2><p>请在插件主页提供明确的问题反馈入口，并说明提交问题时需要携带哪些日志。</p>`,18)])])}const b=e(l,[["render",r]]);export{u as __pageData,b as default};
